use xiom.io;

enum Difficulty {
  Easy,
  Medium,
  Hard,
  Expert,
}

fn Difficulty.max_attempts(self) -> Int {
  match self {
    Easy => { return 10; }
    Medium => { return 5; }
    Hard => { return 3; }
    Expert => { return 1; }
  }
}

fn Difficulty.description(self) -> Str {
  match self {
    Easy => { return "Plenty of chances to learn"; }
    Medium => { return "A fair challenge"; }
    Hard => { return "Mistakes are costly"; }
    Expert => { return "One error and you are done"; }
  }
}

fn main() -> Int {
  let level = Difficulty.Expert;
  return level.max_attempts();
}
